"""Group cover icons generated by PixelLab's Pixen model — the same call
yosubee makes for Yoto icons (`app/services/pixellab_icon_service.rb`).

Generating is synchronous on PixelLab's side (≈30-40s per icon), so the
endpoint that calls this simply awaits it; the app shows a spinner meanwhile.
Every generation is written to ICONS_DIR under an unguessable name and served
as a preview. Choosing one only stores that name on the group, so regenerating
until one looks right never touches the group until the user picks it.
"""

import base64
import binascii
import os
import re
import secrets
from pathlib import Path

import httpx

API_URL = "https://api.pixellab.ai/v2/create-image-pixen"
ICON_SIZE = 16
PROMPT = "generate a 16 x 16 pixel icon that's child friendly that represents a {prompt}"
MAX_PROMPT_CHARS = 200
# Out of credits (402) or throttled (429/529): surfaced apart from failures.
QUOTA_STATUSES = {402, 429, 529}
TIMEOUT = httpx.Timeout(180.0, connect=10.0)

ICONS_DIR = Path("data/group_icons")
# 32 hex chars; anything else is not a file this module wrote.
ICON_NAME = re.compile(r"\A[0-9a-f]{32}\Z")
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


class PixelLabError(Exception):
    pass


class NotConfiguredError(PixelLabError):
    pass


class QuotaExhaustedError(PixelLabError):
    pass


def is_icon_name(name: str | None) -> bool:
    return bool(name) and bool(ICON_NAME.match(name))


def icon_path(name: str) -> Path:
    if not is_icon_name(name):
        raise ValueError(f"not an icon name: {name!r}")
    return ICONS_DIR / f"{name}.png"


def icon_url(name: str | None) -> str | None:
    """Server-relative, like the app's other image paths."""
    return f"/group-icons/{name}.png" if is_icon_name(name) else None


def build_request(prompt: str) -> dict:
    return {
        "description": PROMPT.format(prompt=prompt),
        "image_size": {"width": ICON_SIZE, "height": ICON_SIZE},
        "no_background": True,
    }


def decode_image(payload: dict) -> bytes:
    raw = str((payload.get("image") or {}).get("base64") or "")
    raw = re.sub(r"\Adata:image/\w+;base64,", "", raw)
    if not raw:
        raise PixelLabError("PixelLab returned no image")
    try:
        data = base64.b64decode(raw, validate=False)
    except (binascii.Error, ValueError) as exc:
        raise PixelLabError("PixelLab returned undecodable image data") from exc
    if not data.startswith(PNG_SIGNATURE):
        raise PixelLabError("PixelLab returned something that is not a PNG")
    return data


async def generate(prompt: str, transport: httpx.AsyncBaseTransport | None = None) -> str:
    """Generate an icon for `prompt`, save it, and return its name."""
    token = os.getenv("PIXELLABS_API_TOKEN", "")
    if not token:
        raise NotConfiguredError("PIXELLABS_API_TOKEN not set")
    # trust_env=False: see CLAUDE.md "Every httpx call passes trust_env=False".
    async with httpx.AsyncClient(timeout=TIMEOUT, trust_env=False, transport=transport) as client:
        try:
            resp = await client.post(
                API_URL,
                headers={"Authorization": f"Bearer {token}"},
                json=build_request(prompt),
            )
        except httpx.HTTPError as exc:
            raise PixelLabError(f"PixelLab request failed: {exc.__class__.__name__}") from exc
    if resp.status_code in QUOTA_STATUSES:
        raise QuotaExhaustedError(f"PixelLab quota exhausted ({resp.status_code})")
    if resp.status_code != 200:
        raise PixelLabError(f"PixelLab API error ({resp.status_code}): {resp.text[:300]}")
    try:
        payload = resp.json()
    except ValueError as exc:
        raise PixelLabError("PixelLab returned malformed JSON") from exc
    data = decode_image(payload)

    name = secrets.token_hex(16)
    ICONS_DIR.mkdir(parents=True, exist_ok=True)
    icon_path(name).write_bytes(data)
    return name
